#!/usr/bin/env bash
RED='\033[0;31m'; GRN='\033[0;32m'; YEL='\033[1;33m'; CYA='\033[0;36m'; NC='\033[0m'

info() { printf "${CYA}[i]${NC} %s\n" "$1"; }
ok()   { printf "${GRN}[ok]${NC} %s\n" "$1"; }
warn() { printf "${YEL}[!]${NC} %s\n" "$1"; }
err()  { printf "${RED}[x]${NC} %s\n" "$1" >&2; }

info "{{msg}}"
ok "all green"
